// jet: shared compile-time table types. Tables live in configs_gen.h
// (generated by jet_mlip/tables.py from e3nn instructions).
#pragma once

struct PathT {
  int l1, l2, l3;       // irrep degrees of x, sh, out
  int off1, off2, off3; // block offsets (channel 0) in x / sh / out (mul_ir layout)
  int mul;              // channels of this path (= mul of its x irrep; 8 | mul <= 128)
  int wcol;             // first W column (prefix sum of live path muls)
};

struct FiberT {
  int p;            // live path index
  int m1, m2, m3;   // component indices inside the irrep blocks
  double coef;      // path_weight * wigner_3j[m1][m2][m3]
};

// Index helpers (mul_ir layout). u = channel (< paths[p].mul).
// x   : off1 + u*(2*l1+1) + m1
// sh  : off2 + m2
// W   : paths[p].wcol + u
// out : off3 + u*(2*l3+1) + m3

// ---- compile-time helpers over a config's path table --------------------------------------
// Channel units: unit i = (path p, 32-channel chunk ch), lane = channel inside the chunk,
// u = 32*ch + lane; only lanes < ncol(i) are live (ncol = mul % 32 for the last chunk of a mul-8/16 path).
constexpr int cmin(int a, int b) { return a < b ? a : b; }
template <class Cfg> constexpr int nch_of(int p) { return (Cfg::paths[p].mul + 31) / 32; }
template <class Cfg> constexpr int nchmax() {
  int m = 1;
  for (int p = 0; p < Cfg::NPATH; ++p) m = m > nch_of<Cfg>(p) ? m : nch_of<Cfg>(p);
  return m;
}
template <class Cfg> constexpr int unit_of(int p, int ch) {
  int n = 0;
  for (int q = 0; q < p; ++q) n += nch_of<Cfg>(q);
  return n + ch;
}
template <class Cfg> constexpr int nunits() { return unit_of<Cfg>(Cfg::NPATH, 0); }
template <class Cfg> constexpr int u_path(int i) {
  int n = 0;
  for (int p = 0; p < Cfg::NPATH; ++p) { n += nch_of<Cfg>(p); if (i < n) return p; }
  return Cfg::NPATH - 1;
}
template <class Cfg> constexpr int u_ch(int i) { return i - unit_of<Cfg>(u_path<Cfg>(i), 0); }
template <class Cfg> constexpr int u_ncol(int i) { return cmin(32, Cfg::paths[u_path<Cfg>(i)].mul - 32 * u_ch<Cfg>(i)); }
template <class Cfg> constexpr int u_col(int i) { return Cfg::paths[u_path<Cfg>(i)].wcol + 32 * u_ch<Cfg>(i); }  // W col of lane 0
// out register slot of (path p, m3 = 0): live paths' (2*l3+1) blocks packed in path order
template <class Cfg> constexpr int oslot(int p) {
  int o = 0;
  for (int q = 0; q < p; ++q) o += 2 * Cfg::paths[q].l3 + 1;
  return o;
}
// x blocks: distinct off1 values (one per x irrep used by a live path) in order of first appearance
template <class Cfg> constexpr int xb_of(int p) {
  int idx = 0;
  for (int q = 0; q < p; ++q) {
    bool first = true;
    for (int r = 0; r < q; ++r) if (Cfg::paths[r].off1 == Cfg::paths[q].off1) first = false;
    if (Cfg::paths[q].off1 == Cfg::paths[p].off1) return idx;
    if (first) idx++;
  }
  return idx;
}
template <class Cfg> constexpr int nxb() {
  int n = 0;
  for (int p = 0; p < Cfg::NPATH; ++p) n = n > xb_of<Cfg>(p) + 1 ? n : xb_of<Cfg>(p) + 1;
  return n;
}
template <class Cfg> constexpr int xb_path(int b) {   // a path reading block b
  for (int p = 0; p < Cfg::NPATH; ++p) if (xb_of<Cfg>(p) == b) return p;
  return 0;
}
template <class Cfg> constexpr int xb_l(int b) { return Cfg::paths[xb_path<Cfg>(b)].l1; }
template <class Cfg> constexpr int xb_off(int b) { return Cfg::paths[xb_path<Cfg>(b)].off1; }
template <class Cfg> constexpr int xb_mul(int b) { return Cfg::paths[xb_path<Cfg>(b)].mul; }
template <class Cfg> constexpr int xb_ncol(int b, int ch) { return cmin(32, xb_mul<Cfg>(b) - 32 * ch); }
// x register slot of (block b, m1 = 0): blocks packed in block order
template <class Cfg> constexpr int xslot(int b) {
  int o = 0;
  for (int c = 0; c < b; ++c) o += 2 * xb_l<Cfg>(c) + 1;
  return o;
}
